at::Tensor adagrad_custom_impl_npu(const at::Tensor& param, const at::Tensor& grad, const at::Tensor& accum,
                                   const at::Tensor& lr, const at::Tensor& eps) {
    at::Tensor result = at::empty_like(param);
    EXEC_NPU_CMD(aclnnAdagradCustom, param, grad, accum, lr, eps, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("adagrad_custom", &adagrad_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("adagrad_custom", &adagrad_custom_impl_npu, "Adagrad update: param - lr * grad / (sqrt(accum + grad^2) + eps)");
